PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL,expires_at TEXT NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS acknowledgements(id INTEGER PRIMARY KEY,user_id INTEGER,accepted_at TEXT NOT NULL,version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS authorization_projects(id INTEGER PRIMARY KEY,name TEXT NOT NULL,owner TEXT NOT NULL,scope TEXT NOT NULL,expires_at TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'ACTIVE');

CREATE TABLE IF NOT EXISTS ap_clients(mac TEXT PRIMARY KEY,ip TEXT,hostname TEXT,interface TEXT NOT NULL,first_seen TEXT NOT NULL,last_seen TEXT NOT NULL,state TEXT NOT NULL,source TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ap_activity(id INTEGER PRIMARY KEY,created_at TEXT NOT NULL,event TEXT NOT NULL,mac TEXT,ip TEXT,hostname TEXT,details TEXT NOT NULL DEFAULT '{}');

